def candidates(cells):
    bycell = {c: [] for c in cells}
    cands=[]
    for r in range(7):
        for c in range(7):
            sq={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
            if sq<=cells:
                cands.append((1,frozenset(sq)))
            for missing in range(4):
                shape=set((r+dr,c+dc) for dr,dc in [(0,0),(0,1),(1,0),(1,1)] if (dr*2+dc)!=missing)
                if shape<=cells:
                    # missing map: UL=2, BL=3, TR=4, BR unknown=5
                    lab={0:2,2:3,1:4,3:5}[missing]
                    cands.append((lab,frozenset(shape)))
    for i,(_,s) in enumerate(cands):
        for c in s: bycell[c].append(i)
    return cands,bycell

def tilings(grid, maxn=10000):
    cells={(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==8}
    cs,bc=candidates(cells)
    ans=[]
    def rec(rem,chosen):
        if not rem:
            ans.append(chosen[:]); return len(ans)>=maxn
        cell=min(rem,key=lambda c:sum(cs[i][1]<=rem for i in bc[c]))
        for i in bc[cell]:
            lab,s=cs[i]
            if s<=rem:
                if rec(rem-s,chosen+[(lab,s)]): return True
        return False
    rec(cells,[])
    return ans
